window.products.push({"id":582551,"name":"Rosti Spoon - Solid - Melamine - Lime Yellow","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/11H1pQTjt7L._AC_.jpg","description":"This melamine spoon is extra strong, making it ideal for general purpose use around the kitchen, whether for stirring sauces or serving foods. Melamine is resistant to scratches, stains, and odor transfer. Suitable for cookwares with non- stick coating. The spoon is BPA-free, dishwasher safe and heat resistant up to 180°C. Not intended for use in freezer or microwave. The spoon measures 11.5 x 3.3 x 2.6\" and weighs approximately 0.1 lbs. Color: nordic lemon","images":["https://m.media-amazon.com/images/I/11H1pQTjt7L._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Rosti","source_asin":"B07FQVJ8WM","category_path":"Home & Kitchen"},"sku":"BM-582551","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07FQVJ8WM","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07FQVJ8WM","price_pending":true,"merchant_ready":false});
